//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			Digital Input
//	CREATOR:		Helgevold - William Veim                                                                                                                                                                                                                                                              
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION		DATE				SIGN						DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0				2025-03-17		William Veim			Initial release                                                                                                                                                                                                                                  
//	1.0.1				2025-03-26		Ruben Byman			Bug fix, would not write to output if not in channel fault
//	1.0.2				2025-04-30		Ruben Byman			Added alarm based on signal value
// 1.0.3				2025-07-23		Fredrik Bjerkenes 	Fixed OK states for wrk values, and also changed stateconfig 3/4/5 to look at wrk_value 1/2/3 Instead of Inp_Value 1/2/3.
//	1.0.2				2025-09-04		William Veim			Increased number of input, from 3 to 5
//	1.0.3				2025-09-04		William Veim			Change in simulation, added select state to simulate
//	1.0.4				2025-09-15		William Veim			Increased string input to mach structure length
//	1.0.5				2025-11-20		William Veim			Bugfix input value 6
//	1.0.6				2026-01-15		William Veim			Added logic for updating symbol quality state
//
//===============================================================================================================================
//
//		FUNKSJONALITET:
//		TO BE SET
//
//===============================================================================================================================

(*************************************************************************
 *	INITIAL/SYSTEM VARIABELS
 *************************************************************************)
 
TON_InitialCycles(In:=TRUE, PT:=TIME#10s); //10sec delay after startup (establish communication)
DtToDateStruct(In:=GetTime(), DateStruct=>DateStruct);
Current_Time := TruncTod(DT_TO_TOD(In:=GetTime()), _SEC);

 (*************************************************************************
 *	INITIALIZE VARIABELS
 *************************************************************************)
 
 Ext_DigitalValue.EXT_Alarm.Sts_SupressIfOff_Visible:=FALSE;
 
 IF NOT Ext_DigitalValue.INT_Data.Initialise THEN
	 
	 //State control
	 Ext_DigitalValue.EXT_Engineering.StateCfg_1.Cfg_Quality:=3; //Input module fault = High
	 Ext_DigitalValue.EXT_Engineering.StateCfg_1.Cfg_Alarm:=TRUE; //Input module fault = Alarm
	 Ext_DigitalValue.EXT_Engineering.StateCfg_2.Cfg_Quality:=0; //Value stuck = Diagnostic
	 Ext_DigitalValue.EXT_Engineering.StateCfg_2.Cfg_Alarm:=FALSE; //Value stuck = Not Alarm
	 Ext_DigitalValue.EXT_Engineering.StateCfg_3.Cfg_Quality:=0; //Unstable value = Diagnostic
	 Ext_DigitalValue.EXT_Engineering.StateCfg_3.Cfg_Alarm:=FALSE; //Value stuck = Not Alarm
	 //Rest of state control dependens on input to block
	 
	//Alarm settings
	Ext_DigitalValue.EXT_Alarm.Cfg_SupressDelayOff:=10;
	Ext_DigitalValue.EXT_Alarm.Cfg_AlarmActiveDelay:=10;
	Ext_DigitalValue.EXT_Alarm.Cfg_AlarmActiveDelay:=10;
	
	//Init complete
	Ext_DigitalValue.INT_Data.Initialise:=TRUE;
	
 END_IF;

(*************************************************************************
 *	FAULT CONTROL AND INPUT LOGIC
 *************************************************************************)
 
 //Value stuck
 CASE Ext_DigitalValue.EXT_Engineering.StateCfg_InputStuckStateIndex OF 
	 
	 0: //Use input 1
	 Wrk_ValueStuck_CurrentValue:=Wrk_Value1;
	 
	 1://Use input 2
	 Wrk_ValueStuck_CurrentValue:=Wrk_Value2;
	 
	 2://Use input 3
	 Wrk_ValueStuck_CurrentValue:=Wrk_Value3;
	 
	 3://Use input 4
	 Wrk_ValueStuck_CurrentValue:=Wrk_Value4;
	 
	 4://Use input 5
	 Wrk_ValueStuck_CurrentValue:=Wrk_Value5;
	 
 END_CASE;
 
TON_ValueStuck(In:=Wrk_ValueStuck_CurrentValue=Wrk_ValueStuck_CurrentValue_Sample, 
							PT:=SecToTime(Ext_DigitalValue.EXT_Engineering.StateCfg_InputStuckTimeDelay), 
							Q=>Wrk_ValueStuck);

 //Unsable value
 CASE Ext_DigitalValue.EXT_Engineering.StateCfg_UnstableValueStateIndex OF 
	 
	 0: //Use input 1
	 Wrk_UnstableValue_CurrentValue:=Wrk_Value1;
	 
	 1://Use input 2
	 Wrk_UnstableValue_CurrentValue:=Wrk_Value2;
	 
	 2://Use input 3
	 Wrk_UnstableValue_CurrentValue:=Wrk_Value3;
	 
	 3://Use input 4
	 Wrk_UnstableValue_CurrentValue:=Wrk_Value4;
	 
	 4://Use input 5
	 Wrk_UnstableValue_CurrentValue:=Wrk_Value5;
	 
 END_CASE;

IF Wrk_UnstableValue_CurrentValue<>Wrk_UnstableValue_CurrentValue_Sample THEN
	Inc(Wrk_CountChanges);
END_IF;

Wrk_TimeSpan:=ADD_TIME(In1:=Wrk_TimeSpan, In2:=GetMyTaskInterval());

IF Wrk_TimeSpan >= SecToTime(Ext_DigitalValue.EXT_Engineering.StateCfg_UnstableValueTimeSpan) THEN
	IF Wrk_CountChanges > Ext_DigitalValue.EXT_Engineering.StateCfg_UnstableValueNumberOfChanges THEN
		Wrk_UnstableValue:=TRUE;
		Clear(Wrk_CountChanges);
	ELSE
		Wrk_UnstableValue:=FALSE;
	END_IF;
END_IF;

Wrk_ValueStuck_CurrentValue_Sample:=Wrk_ValueStuck_CurrentValue;
 
Wrk_ModulFault:= 		Inp_ModuleFault AND TON_InitialCycles.Q;;

Wrk_UnstableValue:=	FALSE; //TODO

//INPUT CONTROL

Wrk_Value1:=	Inp_Value1 AND NOT Ext_DigitalValue.EXT_Engineering.StateCfg_4_OK_State
						OR NOT Inp_Value1 AND Ext_DigitalValue.EXT_Engineering.StateCfg_4_OK_State;
								
Wrk_Value2:=	Inp_Value2 AND NOT Ext_DigitalValue.EXT_Engineering.StateCfg_5_OK_State
						OR NOT Inp_Value2 AND Ext_DigitalValue.EXT_Engineering.StateCfg_5_OK_State;
								
Wrk_Value3:=	Inp_Value3 AND NOT Ext_DigitalValue.EXT_Engineering.StateCfg_6_OK_State
						OR NOT Inp_Value3 AND Ext_DigitalValue.EXT_Engineering.StateCfg_6_OK_State;
								
Wrk_Value4:=	Inp_Value4 AND NOT Ext_DigitalValue.EXT_Engineering.StateCfg_7_OK_State
						OR NOT Inp_Value4 AND Ext_DigitalValue.EXT_Engineering.StateCfg_7_OK_State;
								
Wrk_Value5:=	Inp_Value5 AND NOT Ext_DigitalValue.EXT_Engineering.StateCfg_8_OK_State
						OR NOT Inp_Value5 AND Ext_DigitalValue.EXT_Engineering.StateCfg_8_OK_State;
						
Wrk_Value6:=	Inp_Value6 AND NOT Ext_DigitalValue.EXT_Engineering.StateCfg_9_OK_State
						OR NOT Inp_Value6 AND Ext_DigitalValue.EXT_Engineering.StateCfg_9_OK_State;
						
Wrk_Value7:=	Inp_Value7 AND NOT Ext_DigitalValue.EXT_Engineering.StateCfg_10_OK_State
						OR NOT Inp_Value7 AND Ext_DigitalValue.EXT_Engineering.StateCfg_10_OK_State;
						
Wrk_Value8:=	Inp_Value8 AND NOT Ext_DigitalValue.EXT_Engineering.StateCfg_11_OK_State
						OR NOT Inp_Value8 AND Ext_DigitalValue.EXT_Engineering.StateCfg_11_OK_State;
				
Wrk_Value9:=	Inp_Value9 AND NOT Ext_DigitalValue.EXT_Engineering.StateCfg_12_OK_State
						OR NOT Inp_Value9 AND Ext_DigitalValue.EXT_Engineering.StateCfg_12_OK_State;

 (*************************************************************************
 *	SIMULATION OF VALUE 
 *************************************************************************)
 
 IF Ext_DigitalValue.EXT_Engineering.Simulate_Active THEN
	 
	 CASE Ext_DigitalValue.EXT_Engineering.Simulate_StateIndex OF
		 
		 0: //Module fault
		 Wrk_ModulFault:=Ext_DigitalValue.EXT_Engineering.Simulate_Value;
		 
		 1: //Value stuck
		 Wrk_ValueStuck:=Ext_DigitalValue.EXT_Engineering.Simulate_Value;
		 
		 2://Unstable value
		 Wrk_UnstableValue:=Ext_DigitalValue.EXT_Engineering.Simulate_Value;
		 
		 3://Spare
		 Wrk_Spare:=Ext_DigitalValue.EXT_Engineering.Simulate_Value;
		 
		 4://Input 1
		 Wrk_Value1:=Ext_DigitalValue.EXT_Engineering.Simulate_Value;
		 
		 5://Input 2
		 Wrk_Value2:=Ext_DigitalValue.EXT_Engineering.Simulate_Value;
		 
		6://Input 3
	 	Wrk_Value3:=Ext_DigitalValue.EXT_Engineering.Simulate_Value;
		
		7://Input 4
	 	Wrk_Value4:=Ext_DigitalValue.EXT_Engineering.Simulate_Value;
		
		8://Input 5
	 	Wrk_Value5:=Ext_DigitalValue.EXT_Engineering.Simulate_Value;
		
		9://Input 6
	 	Wrk_Value6:=Ext_DigitalValue.EXT_Engineering.Simulate_Value;
		
	 END_CASE;

	 Ext_DigitalValue.EXT_General.Sts_Quality:=5;//QUALITY TO SIMULATE
	 
 END_IF;

(*************************************************************************
 *	FAULT AND STATE CONTROL
 *************************************************************************)

//Resetter variabler før løkke
Ext_DigitalValue.EXT_General.Sts_Quality := 6; //Good
Wrk_ActionState := 0;

//Input module fault
HE_StateControl(EXT_StateData:=Ext_DigitalValue.EXT_Engineering.StateCfg_1, 
							Inp_Visibility:=TRUE, 
							Inp_State:=Wrk_ModulFault, 
							Inp_Desc:='Input module fault', 
							Sts_Quality:=Ext_DigitalValue.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[0].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[0].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[0].Alm_Priority);


//Input stuck
HE_StateControl(EXT_StateData:=Ext_DigitalValue.EXT_Engineering.StateCfg_2, 
							Inp_Visibility:=Ext_DigitalValue.EXT_Engineering.StateCfg_InputStuckVisible, 
							Inp_State:=Wrk_ValueStuck, 
							Inp_Desc:='Value stuck', 
							Sts_Quality:=Ext_DigitalValue.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[1].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[1].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[1].Alm_Priority);

//Unstable value
HE_StateControl(EXT_StateData:=Ext_DigitalValue.EXT_Engineering.StateCfg_3, 
							Inp_Visibility:=Ext_DigitalValue.EXT_Engineering.StateCfg_UnstableValueVisible, 
							Inp_State:=Wrk_UnstableValue, 
							Inp_Desc:='Unstable value', 
							Sts_Quality:=Ext_DigitalValue.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[2].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[2].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[2].Alm_Priority);

//Input value 1
HE_StateControl(EXT_StateData:=Ext_DigitalValue.EXT_Engineering.StateCfg_4, 
							Inp_Visibility:=Inp_Value1_Suffix<>'', 
							Inp_State:=Wrk_Value1, 
							Inp_Desc:=Inp_Value1_Suffix, 
							Sts_Quality:=Ext_DigitalValue.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[3].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[3].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[3].Alm_Priority);

//Input value 2
HE_StateControl(EXT_StateData:=Ext_DigitalValue.EXT_Engineering.StateCfg_5, 
							Inp_Visibility:=Inp_Value2_Suffix<>'', 
							Inp_State:=Wrk_Value2, 
							Inp_Desc:=Inp_Value2_Suffix, 
							Sts_Quality:=Ext_DigitalValue.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[4].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[4].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[4].Alm_Priority);

//Input value 3
HE_StateControl(EXT_StateData:=Ext_DigitalValue.EXT_Engineering.StateCfg_6, 
							Inp_Visibility:=Inp_Value3_Suffix<>'', 
							Inp_State:=Wrk_Value3, 
							Inp_Desc:=Inp_Value3_Suffix, 
							Sts_Quality:=Ext_DigitalValue.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[5].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[5].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[5].Alm_Priority);

//Input value 4
HE_StateControl(EXT_StateData:=Ext_DigitalValue.EXT_Engineering.StateCfg_7, 
							Inp_Visibility:=Inp_Value4_Suffix<>'', 
							Inp_State:=Wrk_Value4, 
							Inp_Desc:=Inp_Value4_Suffix, 
							Sts_Quality:=Ext_DigitalValue.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[6].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[6].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[6].Alm_Priority);

//Input value 5
HE_StateControl(EXT_StateData:=Ext_DigitalValue.EXT_Engineering.StateCfg_8, 
							Inp_Visibility:=Inp_Value5_Suffix<>'', 
							Inp_State:=Wrk_Value5, 
							Inp_Desc:=Inp_Value5_Suffix, 
							Sts_Quality:=Ext_DigitalValue.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[7].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[7].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[7].Alm_Priority);

//Input value 6
HE_StateControl(EXT_StateData:=Ext_DigitalValue.EXT_Engineering.StateCfg_9, 
							Inp_Visibility:=Inp_Value6_Suffix<>'', 
							Inp_State:=Wrk_Value6, 
							Inp_Desc:=Inp_Value6_Suffix, 
							Sts_Quality:=Ext_DigitalValue.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[8].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[8].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[8].Alm_Priority);

//Input value 7
HE_StateControl(EXT_StateData:=Ext_DigitalValue.EXT_Engineering.StateCfg_10, 
							Inp_Visibility:=Inp_Value7_Suffix<>'', 
							Inp_State:=Wrk_Value7, 
							Inp_Desc:=Inp_Value7_Suffix, 
							Sts_Quality:=Ext_DigitalValue.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[9].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[9].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[9].Alm_Priority);

//Input value 8
HE_StateControl(EXT_StateData:=Ext_DigitalValue.EXT_Engineering.StateCfg_11, 
							Inp_Visibility:=Inp_Value8_Suffix<>'', 
							Inp_State:=Wrk_Value8, 
							Inp_Desc:=Inp_Value8_Suffix, 
							Sts_Quality:=Ext_DigitalValue.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[10].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[10].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[10].Alm_Priority);

//Input value 9
HE_StateControl(EXT_StateData:=Ext_DigitalValue.EXT_Engineering.StateCfg_12, 
							Inp_Visibility:=Inp_Value9_Suffix<>'', 
							Inp_State:=Wrk_Value9, 
							Inp_Desc:=Inp_Value9_Suffix, 
							Sts_Quality:=Ext_DigitalValue.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[11].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[11].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[11].Alm_Priority);

 (*************************************************************************
 *	VALUE CONTROL (Based on state) - NB! NOT IN USE
 *************************************************************************)



(*************************************************************************
 *	EXCECUTING ALARM BLOCK
 *************************************************************************)
 
 FB_AlarmGeneral(ENS:=TRUE, 
								 Ext_Alarm:=Ext_DigitalValue.EXT_Alarm, 
								 Int_Alarm:=Int_Alarm, 
								 Inp_AlarmData:=Wrk_AlarmData,
								 Inp_LocationData:=Ext_DigitalValue.EXT_General.LocationIndex,
								 Inp_AlarmSupress:=Inp_AlmSuppress, 
								 Inp_AlmSuppressDesc:=Inp_AlmSuppressDesc, 
								 Inp_Connected_Cabinet:=Cfg_ControlCabinet, 
								 Inp_Connected_Controller:=Cfg_ControllerTAG, 
								 Inp_Process_TAG:=Cfg_ProcessTAG, 
								 Inp_Process_Desc:=Ext_DigitalValue.EXT_General.Process_Desc,
								 Inp_Process_Value:='', //Not relevant
								 Out_AlarmToken=>Wrk_AlarmToken, 
								 Out_AlarmTriggered=>Wrk_AlarmTriggered);
 
(*************************************************************************
 *	STATISTICS
 *************************************************************************)

RE_InpValue1(Clk:=Inp_Value1);
RE_InpValue2(Clk:=Inp_Value2);
RE_InpValue3(Clk:=Inp_Value3);
RE_InpValue4(Clk:=Inp_Value4);
RE_InpValue5(Clk:=Inp_Value5);
RE_InpValue6(Clk:=Inp_Value6);
RE_InpValue7(Clk:=Inp_Value7);
RE_InpValue8(Clk:=Inp_Value8);
RE_InpValue9(Clk:=Inp_Value9);

IF RE_InpValue1.Q THEN
	Ext_DigitalValue.EXT_Statistics.StateCfg_4_ChangesToday:= Ext_DigitalValue.EXT_Statistics.StateCfg_4_ChangesToday + 1;
END_IF;

IF RE_InpValue2.Q THEN
	Ext_DigitalValue.EXT_Statistics.StateCfg_5_ChangesToday:= Ext_DigitalValue.EXT_Statistics.StateCfg_5_ChangesToday + 1;
END_IF;

IF RE_InpValue3.Q THEN
	Ext_DigitalValue.EXT_Statistics.StateCfg_6_ChangesToday:= Ext_DigitalValue.EXT_Statistics.StateCfg_6_ChangesToday + 1;
END_IF;

IF RE_InpValue4.Q THEN
	Ext_DigitalValue.EXT_Statistics.StateCfg_7_ChangesToday:= Ext_DigitalValue.EXT_Statistics.StateCfg_7_ChangesToday + 1;
END_IF;

IF RE_InpValue5.Q THEN
	Ext_DigitalValue.EXT_Statistics.StateCfg_8_ChangesToday:= Ext_DigitalValue.EXT_Statistics.StateCfg_8_ChangesToday + 1;
END_IF;

IF RE_InpValue6.Q THEN
	Ext_DigitalValue.EXT_Statistics.StateCfg_9_ChangesToday:= Ext_DigitalValue.EXT_Statistics.StateCfg_9_ChangesToday + 1;
END_IF;

IF RE_InpValue7.Q THEN
	Ext_DigitalValue.EXT_Statistics.StateCfg_10_ChangesToday:= Ext_DigitalValue.EXT_Statistics.StateCfg_10_ChangesToday + 1;
END_IF;

IF RE_InpValue8.Q THEN
	Ext_DigitalValue.EXT_Statistics.StateCfg_11_ChangesToday:= Ext_DigitalValue.EXT_Statistics.StateCfg_11_ChangesToday + 1;
END_IF;

IF RE_InpValue9.Q THEN
	Ext_DigitalValue.EXT_Statistics.StateCfg_12_ChangesToday:= Ext_DigitalValue.EXT_Statistics.StateCfg_12_ChangesToday + 1;
END_IF;

 //Checks if new day
 IF Sample_Day <> DateStruct.Day THEN
	Clear(Ext_DigitalValue.EXT_Statistics.StateCfg_4_ChangesToday);
	Clear(Ext_DigitalValue.EXT_Statistics.StateCfg_5_ChangesToday);
	Clear(Ext_DigitalValue.EXT_Statistics.StateCfg_6_ChangesToday);
	Clear(Ext_DigitalValue.EXT_Statistics.StateCfg_7_ChangesToday);
	Clear(Ext_DigitalValue.EXT_Statistics.StateCfg_8_ChangesToday);
	Clear(Ext_DigitalValue.EXT_Statistics.StateCfg_9_ChangesToday);
	Clear(Ext_DigitalValue.EXT_Statistics.StateCfg_10_ChangesToday);
	Clear(Ext_DigitalValue.EXT_Statistics.StateCfg_11_ChangesToday);
	Clear(Ext_DigitalValue.EXT_Statistics.StateCfg_12_ChangesToday);
	Sample_Day:=DateStruct.Day;
END_IF;

(*************************************************************************
 *	UPDATING OUTPUT AND STRUCTURE
 *************************************************************************)

//OUTPUT
Sts_AlarmToken:=Wrk_AlarmToken;
Sts_AlarmTriggered:=Wrk_AlarmTriggered;

//STRUCTURE
Ext_DigitalValue.EXT_General.Process_TAG:=Cfg_ProcessTAG;
Ext_DigitalValue.EXT_General.Connected_ControlCabinet:=Cfg_ControlCabinet;
Ext_DigitalValue.EXT_General.Controlled_FromController:=Cfg_ControllerTAG;
